SELECT
    participant_id, task_id, member_id, status, complete_time, complete_remark,
    complete_images, reject_reason, deleted_flag, create_time, update_time
FROM t_task_participant
WHERE task_id = #{taskId}
  AND member_id = #{memberId}
  AND deleted_flag = #{deletedFlag}
LIMIT 1

mapper.update:
UPDATE t_task_participant
SET status = #{status}, update_time = #{updateTime}
WHERE participant_id = #{participantId}
  AND deleted_flag = 0
  AND status = #{expectStatus}

UPDATE t_task_participant
SET status = #{status},
    complete_time = #{completeTime},
    complete_remark = #{remark},
    complete_images = #{images},
    update_time = #{updateTime}
WHERE participant_id = #{participantId}
  AND deleted_flag = 0
  AND status = #{expectStatus}

UPDATE t_task_participant
SET status = #{status},
    reject_reason = #{reason},
    update_time = #{updateTime}
WHERE participant_id = #{participantId}
  AND deleted_flag = 0
  AND status = #{expectStatus}

UPDATE t_task_participant
SET status = #{targetStatus}, update_time = #{updateTime}
WHERE task_id = #{taskId}
  AND deleted_flag = 0
  AND member_id <> #{excludeMemberId}
  AND status IN

